COMMIT = "db84b9007461b4753bd03474d38490cf4f13569e"
PARSER = __import__("tree_sitter_language_pack").get_parser("php")

def psql(sql):
    command = [
        "docker", "compose", "-f", COMPOSE, "exec", "-T", SERVICE, "sh", "-lc",
        'psql -X -v ON_ERROR_STOP=1 -P pager=off -U "$POSTGRES_SIMPLE_USER" -d "$POSTGRES_DB"',
    ]
    result = subprocess.run(command, input=sql, text=True, capture_output=True)
    if result.returncode:
        raise RuntimeError("Database command failed: " + result.stderr[-2000:])
    return result.stdout.strip()

query = f"""SELECT COALESCE(json_agg(row_to_json(q)), '[]'::json)::text
FROM (
  SELECT s.id::text AS id, f.path, s.kind, s.name, s.qualified_name,
         s.start_line, s.end_line, s.parent_symbol_id::text AS parent_id,
         s.signature
  FROM aic_symbols s
  JOIN aic_files f ON f.id = s.file_id
  WHERE s.project_id = '{PROJECT_ID}' AND f.project_id = '{PROJECT_ID}'
    AND f.language = 'php' AND f.is_deleted = false
  ORDER BY f.path, s.start_line, s.kind, s.name
) q;"""
rows = json.loads(psql(query))
by_file = defaultdict(list)
for row in rows:
    by_file[row["path"]].append(row)

class_kinds = {"class", "interface", "trait", "enum"}
symbol_by_loc = {}
class_by_qn = {}
class_by_short = defaultdict(list)
methods_by_class = defaultdict(dict)
functions_by_qn = {}
for item in rows:
    item["line"] = int(item["start_line"])
    item["parent_id"] = item["parent_id"]
    symbol_by_loc[(item["path"], item["line"], item["kind"], item["name"])] = item
    if item["kind"] in class_kinds and item["qualified_name"]:
        key = item["qualified_name"].lstrip("\\\\").lower()
        class_by_qn[key] = item
        class_by_short[item["name"].lower()].append(item)
for item in rows:
    if item["kind"] == "method" and item["parent_id"]:
        methods_by_class[item["parent_id"]][item["name"].lower()] = item

edges = {}
parsed_files = set()
parse_errors = []
skipped_files = []
edge_types = defaultdict(int)

def txt(node):
    return node.text.decode("utf-8", "replace").strip()

def children_of_type(node, types):
    return [child for child in node.children if child.type in types]

def descendants(node, types):
    found = []
    stack = list(reversed(node.children))
    while stack:
        current = stack.pop()
        if current.type in types:
            found.append(current)
        stack.extend(reversed(current.children))
    return found

def simple_name(node):
    return re.sub(r"^\\\\+", "", txt(node)).strip()

def add_edge(source, target, target_name, kind, line, path, node_type, confidence=1.0):
    if source is None or (target is None and not target_name):
        return
    evidence = {
        "extractor": "tree-sitter",
        "evidence_kind": kind,
        "source_path": path,
        "ast_node": node_type,
    }
    edge = {
        "source_symbol_id": source["id"],
        "target_symbol_id": target["id"] if target else None,
        "target_qualified_name": None if target else target_name,
        "relation_type": kind,
        "source_line": line,
        "confidence": confidence,
        "evidence": evidence,
    }
    key = (edge["source_symbol_id"], edge["target_symbol_id"], edge["target_qualified_name"], kind, line)
    edges[key] = edge

def imports_for(root):
    imports = {}
    namespace = ""
    for node in descendants(root, {"namespace_definition"}):
        name_node = next((c for c in node.children if c.type in {"namespace_name", "name"}), None)
        if name_node:
            namespace = simple_name(name_node)
            break
    for node in descendants(root, {"namespace_use_declaration"}):
        raw = txt(node)
        raw = re.sub(r"^use\\\\s+(function|const)\\\\s+", "use ", raw)
        raw = re.sub(r"^use\\\\s+", "", raw).rstrip(";").strip()
        if "{" in raw and "}" in raw:
            prefix, grouped = raw.split("{", 1)
            prefix = prefix.rstrip("\\\\").strip()
            grouped = grouped.split("}", 1)[0]
            clauses = [prefix + "\\\\" + part.strip() for part in grouped.split(",") if part.strip()]
        else:
            clauses = [part.strip() for part in raw.split(",") if part.strip()]
        for clause in clauses:
            clause = re.sub(r"^(function|const)\\\\s+", "", clause).strip()
            parts = re.split(r"\\\\s+as\\\\s+", clause, flags=re.I)
            qn = parts[0].lstrip("\\\\")
            alias = parts[1] if len(parts) > 1 else qn.split("\\\\")[-1]
            imports[alias.lower()] = qn
    return namespace, imports

def resolve_class(name, namespace, imports, current_class=None, parent_qn=None):
    name = name.strip().strip("()")
    if not name:
        return None, None
    special = name.lower()
    if special in {"self", "static"} and current_class:
        return current_class, current_class["qualified_name"]
    if special == "parent" and parent_qn:
        return class_by_qn.get(parent_qn.lstrip("\\\\").lower()), parent_qn
    normalized = name.lstrip("\\\\")
    first, sep, rest = normalized.partition("\\\\")
    if first.lower() in imports:
        resolved = imports[first.lower()] + (("\\\\" + rest) if sep else "")
    elif name.startswith("\\\\"):
        resolved = normalized
    elif "\\\\" in normalized:
        resolved = (namespace + "\\\\" + normalized) if namespace else normalized
    else:
        imported = imports.get(normalized.lower())
        resolved = imported or ((namespace + "\\\\" + normalized) if namespace else normalized)
    target = class_by_qn.get(resolved.lstrip("\\\\").lower())
    if target is None and "\\\\" not in normalized and normalized.lower() not in imports:
        candidates = class_by_short.get(normalized.lower(), [])
        if len(candidates) == 1:
            target = candidates[0]
            resolved = target["qualified_name"]
    return target, resolved

for path, file_symbols in by_file.items():
    abs_path = ROOT / path
    if not abs_path.is_file():
        skipped_files.append(path)
        continue
    source = abs_path.read_bytes()
    tree = PARSER.parse(source)
    if tree.root_node.has_error:
        parse_errors.append(path)
        continue
    parsed_files.add(path)
    root = tree.root_node
    namespace, imports = imports_for(root)

    class_nodes = descendants(root, {"class_declaration", "interface_declaration", "trait_declaration", "enum_declaration"})
    class_context = {}
    for class_node in class_nodes:
        name_node = class_node.child_by_field_name("name")
        if name_node is None:
            continue
        class_name = txt(name_node)
        class_symbol = symbol_by_loc.get((path, class_node.start_point[0] + 1, class_node.type.replace("_declaration", ""), class_name))
        if not class_symbol:
            class_symbol = next((s for s in file_symbols if s["kind"] in class_kinds and s["name"] == class_name and s["line"] == class_node.start_point[0] + 1), None)
        if not class_symbol:
            continue
        class_context[class_node.id] = class_symbol
        parent_qn = None
        for base in children_of_type(class_node, {"base_clause"}):
            for ref in descendants(base, {"name", "qualified_name"}):
                target, target_qn = resolve_class(simple_name(ref), namespace, imports)
                parent_qn = target_qn
                add_edge(class_symbol, target, target_qn, "extends", ref.start_point[0] + 1, path, ref.type)
        for clause in children_of_type(class_node, {"class_interface_clause"}):
            for ref in children_of_type(clause, {"name", "qualified_name"}):
                target, target_qn = resolve_class(simple_name(ref), namespace, imports)
                add_edge(class_symbol, target, target_qn, "implements", ref.start_point[0] + 1, path, ref.type)
        body = class_node.child_by_field_name("body")
        if body:
            for use_node in children_of_type(body, {"use_declaration"}):
                for ref in children_of_type(use_node, {"name", "qualified_name"}):
                    target, target_qn = resolve_class(simple_name(ref), namespace, imports, class_symbol, parent_qn)
                    add_edge(class_symbol, target, target_qn, "uses", ref.start_point[0] + 1, path, ref.type)

    # File imports are represented from the indexed top-level declarations in that file.
    top_level_sources = [s for s in file_symbols if s["kind"] in class_kinds | {"function"} and not s["parent_id"]]
    for use_node in descendants(root, {"namespace_use_declaration"}):
        raw = txt(use_node)
        raw = re.sub(r"^use\\\\s+", "", raw).rstrip(";").strip()
        clauses = [raw]
        if "{" in raw and "}" in raw:
            prefix, grouped = raw.split("{", 1)
            clauses = [prefix.rstrip("\\\\").strip() + "\\\\" + part.strip() for part in grouped.split("}", 1)[0].split(",") if part.strip()]
        for clause in clauses:
            parts = re.split(r"\\\\s+as\\\\s+", clause, flags=re.I)
            imported_qn = parts[0].lstrip("\\\\")
            target = class_by_qn.get(imported_qn.lower())
            for source_symbol in top_level_sources:
                if target and source_symbol["id"] != target["id"]:
                    add_edge(source_symbol, target, imported_qn, "imports", use_node.start_point[0] + 1, path, "namespace_use_declaration")

    methods = descendants(root, {"method_declaration", "function_definition"})
    for method_node in methods:
        method_name_node = method_node.child_by_field_name("name")
        if method_name_node is None:
            continue
        method_name = txt(method_name_node)
        method_line = method_node.start_point[0] + 1
        kind = "function" if method_node.type == "function_definition" else "method"
        source_symbol = symbol_by_loc.get((path, method_line, kind, method_name))
        if source_symbol is None:
            source_symbol = next((s for s in file_symbols if s["kind"] == kind and s["name"] == method_name and s["line"] == method_line), None)
        if source_symbol is None:
            continue
        enclosing_class = None
        ancestor = method_node.parent
        while ancestor:
            if ancestor.id in class_context:
                enclosing_class = class_context[ancestor.id]
                break
            ancestor = ancestor.parent
        parent_qn = None
        if enclosing_class:
            class_node = next((n for n in class_nodes if n.id in class_context and class_context[n.id]["id"] == enclosing_class["id"]), None)
            if class_node:
                for base in children_of_type(class_node, {"base_clause"}):
                    ref = next(iter(descendants(base, {"name", "qualified_name"})), None)
                    if ref:
                        _, parent_qn = resolve_class(simple_name(ref), namespace, imports)
        body = method_node.child_by_field_name("body")
        if body is None:
            continue
        for new_node in descendants(body, {"object_creation_expression"}):
            class_ref = next((c for c in new_node.children if c.type in {"name", "qualified_name"}), None)
            if class_ref:
                target, qn = resolve_class(simple_name(class_ref), namespace, imports, enclosing_class, parent_qn)
                add_edge(source_symbol, target, qn, "instantiates", new_node.start_point[0] + 1, path, new_node.type)
        for call in descendants(body, {"member_call_expression", "scoped_call_expression", "function_call_expression"}):
            name_node = call.child_by_field_name("name")
            if name_node is None:
                continue
            called_name = txt(name_node)
            if call.type == "member_call_expression":
                obj = call.child_by_field_name("object")
                obj_text = txt(obj) if obj else ""
                target_class = None
                target_qn = None
                if obj_text in {"$this", "$this->"} and enclosing_class:
                    target_class = enclosing_class
                    target_qn = enclosing_class["qualified_name"]
                if target_class:
                    target_method = methods_by_class.get(target_class["id"], {}).get(called_name.lower())
                    if target_method:
                        add_edge(source_symbol, target_method, None, "calls", call.start_point[0] + 1, path, call.type)
                    else:
                        add_edge(source_symbol, None, target_qn + "::" + called_name, "calls", call.start_point[0] + 1, path, call.type, 0.85)
            elif call.type == "scoped_call_expression":
                scope = call.child_by_field_name("scope")
                scope_text = simple_name(scope) if scope else ""
                target_class, target_qn = resolve_class(scope_text, namespace, imports, enclosing_class, parent_qn)
                target_method = methods_by_class.get(target_class["id"], {}).get(called_name.lower()) if target_class else None
                if target_method:
                    add_edge(source_symbol, target_method, None, "calls", call.start_point[0] + 1, path, call.type)
                elif target_qn:
                    add_edge(source_symbol, None, target_qn + "::" + called_name, "calls", call.start_point[0] + 1, path, call.type, 0.85)
            else:
                fn_name = simple_name(call.child_by_field_name("function"))
                if "\\\\" in fn_name or namespace:
                    fqfn = fn_name.lstrip("\\\\") if fn_name.startswith("\\\\") else namespace + "\\\\" + fn_name
                    target_fn = functions_by_qn.get(fqfn.lower())
                else:
                    target_fn = functions_by_qn.get(fn_name.lower())
                if target_fn:
                    add_edge(source_symbol, target_fn, None, "calls", call.start_point[0] + 1, path, call.type)

    # index local functions for function-call resolution after parsing each file below
    for s in file_symbols:
        if s["kind"] == "function":
            fqfn = s["qualified_name"] or ((namespace + "\\\\" + s["name"]) if namespace else s["name"])
            functions_by_qn[fqfn.lstrip("\\\\").lower()] = s

# Resolve remaining exact local class targets after all indexed symbols are loaded.
for edge in edges.values():
    if edge["target_symbol_id"] is None and edge["target_qualified_name"]:
        candidate = class_by_qn.get(edge["target_qualified_name"].split("::", 1)[0].lstrip("\\\\").lower())
        if candidate and "::" not in edge["target_qualified_name"]:
            edge["target_symbol_id"] = candidate["id"]
            edge["target_qualified_name"] = None

